```javascript
const input = require('fs').readFileSync(0, 'utf8').trim();
const suits = ['C', 'E', 'U', 'P'];
const cards = Object.fromEntries(suits.map(suit => [suit, new Set()]));
const duplicated = Object.fromEntries(suits.map(suit => [suit, false]));

for (let i = 0; i < input.length; i += 3) {
  const value = input.slice(i, i + 2);
  const suit = input[i + 2];

  if (cards[suit].has(value)) {
    duplicated[suit] = true;
  } else {
    cards[suit].add(value);
  }
}

console.log(suits.map(suit =>
  duplicated[suit] ? 'erro' : String(13 - cards[suit].size)
).join('\n'));
